pub struct UserId(u64);

impl UserId {
    pub fn parse(raw: u64) -> Result<Self, IdError> {
        (raw != 0).then_some(UserId(raw)).ok_or(IdError::Zero)
    }
    pub fn get(self) -> u64 { self.0 }
}

